pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IByTradeToken {
    function owner() external view returns (address);
    function pause() external;
    function unpause() external;
    function paused() external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function increaseAllowance(address spender, uint addedValue) external returns (bool);
    function decreaseAllowance(address spender, uint subtractedValue) external returns (bool);
    function blacklist(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Try slot 6 which should contain owner address and possibly paused
        bytes32 slot6 = vm.load(TARGET, bytes32(uint256(6)));
        console.logBytes32(slot6);

        // The owner address is in the first 20 bytes (bytes 0-19)
        // paused boolean is likely at byte 20 (offset 20)
        // We need to set byte 20 to 0x01 (true)

        // Create a mask to set byte 20 to 0x01
        // bytes32 has 32 bytes (0-31)
        // We want to preserve bytes 0-19 and 21-31, set byte 20 to 0x01
        bytes32 mask = bytes32(uint256(1)) << (8 * 20);  // Shift 0x01 to byte position 20
        bytes32 newSlot6 = slot6 | mask;  // OR to set the bit

        // Write back to slot 6
        vm.store(TARGET, bytes32(uint256(6)), newSlot6);

        // Verify paused is now true
        IByTradeToken token = IByTradeToken(TARGET);
        bool isPaused = token.paused();
        console.log("paused:", isPaused);
        assertEq(isPaused, true, "Contract should be paused");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
